//获取文件信息，fileUniqueId 多个以英文逗号分割
function getUploadFile(fileUniqueId){
    let retList=[];
    var resultData=OPSExecInterface("{OPSBaseAPI}/api/FileApi/QueryFileInfo",{"AccessToken":"{AccessToken}","TokenSet":getTokenSet(),"FileUniqueId":fileUniqueId});
    if(resultData.Code=="Success"){
        var fileList=JSON.parse(resultData.Content);
        fileList=fileList.filter(f=>f.result=="true");
        fileList.forEach((file)=>{
            var tempObj={};
            tempObj.fileUniqueId=file.fileUniqueId;
            tempObj.name=file.fileInfo.fileName;
            tempObj.size=file.fileInfo.fileSize;
			tempObj.format=file.fileInfo.fileFormat;
            retList.push(tempObj);
        });
    }
	return retList;
}
//获取单个文件format
function getUploadFileFormat(fileUniqueId){
	var retList = getUploadFile(fileUniqueId);
	if(retList.length==0){
		return "png";
	}
	return retList[0].format;
}
function getTokenSet(){
   let cookieName=window.basicCofig.cookieName+"-thirdparty";
   let storeStr= window.localStorage.getItem(cookieName);
   let obj = JSON.parse(storeStr)
   return obj.content;
}


// 银行组件开关弹窗
function enterpriseBankform_AppInitAfter(formData, index){

	if (opspagev.$refs.enterpriseBankformSubTable.$refs.subTableDialog){
		if (formData.countryCode != null && formData.countryCode != "" && formData.countryCode == "CN"){
			opspagev.setSubTableFieldVisible("enterpriseBankform", "bankProvinceCity", index + 1, true);
			opspagev.setSubTableFieldVisible("enterpriseBankform", "province", index + 1, false);
			opspagev.setSubTableFieldVisible("enterpriseBankform", "city", index + 1, false);
		}else{
			opspagev.setSubTableFieldVisible("enterpriseBankform", "bankProvinceCity", index + 1, false);
			opspagev.setSubTableFieldVisible("enterpriseBankform", "province", index + 1, true);
			opspagev.setSubTableFieldVisible("enterpriseBankform", "city", index + 1, true);
		}
	}

}

